import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import fa from './fa.json';
import en from './en.json';

const savedLng = typeof localStorage !== 'undefined' ? localStorage.getItem('rame-locale') : null;

function setDir(lang: string) {
  if (typeof document === 'undefined') return;
  const isRtl = lang.startsWith('fa');
  document.documentElement.dir = isRtl ? 'rtl' : 'ltr';
  document.documentElement.lang = isRtl ? 'fa' : 'en';
}

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      fa: { translation: fa },
      en: { translation: en },
    },
    lng: savedLng || 'fa',
    fallbackLng: 'en',
    debug: false,
    interpolation: {
      escapeValue: false,
    },
    detection: {
      order: ['localStorage', 'navigator', 'htmlTag'],
      caches: ['localStorage'],
    },
  });

i18n.on('languageChanged', (lng) => {
  setDir(lng);
  if (typeof localStorage !== 'undefined') {
    localStorage.setItem('rame-locale', lng);
  }
});

// Initialize dir on first load
setDir(i18n.language);

export default i18n;

import React, { useState } from 'react';
