} from 'lucide-react';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { ThemeToggle } from '@/components/antigravity/ThemeToggle';
import { LocaleSwitcher } from '@/components/antigravity/LocaleSwitcher';
