interface NavbarProps {
  className?: string;
}

const navItems = [
  { key: 'home', href: '/', label: 'navbar.home' },
  { key: 'services', href: '/services', label: 'navbar.services' },
  { key: 'packages', href: '/packages', label: 'navbar.packages' },
  { key: 'portfolio', href: '/portfolio', label: 'navbar.portfolio' },
  { key: 'about', href: '/about', label: 'navbar.about' },
  { key: 'blog', href: '/blog', label: 'navbar.blog' },
  { key: 'contact', href: '/contact', label: 'navbar.contact' },
];

export function Navbar({ className }: NavbarProps) {
  const { t, i18n } = useTranslation();
  const isRtl = i18n.language.startsWith('fa');
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <nav
      className={cn(
        'sticky top-0 z-40 w-full border-b border-border bg-surface/80 backdrop-blur-md transition-colors duration-300',
        className
      )}
    >
      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6 lg:px-8">
        {/* Brand */}
        <div className="flex items-center gap-2">
