          </div>
        </div>

        {/* Desktop nav */}
        <div className="hidden md:flex items-center gap-1 sm:gap-3">
          {navItems.map((item) => (
            <Link
              key={item.key}
              to={item.href}
              className="text-sm font-medium text-text-secondary hover:text-primary transition-colors"
            >
              {t(item.label)}
