import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Mail, Phone, MessageSquare } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sileo';
import apiClient from '@/lib/apiClient';

interface ContactFormProps {
  className?: string;
}

export function ContactForm({ className }: ContactFormProps) {
  const { t } = useTranslation();
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: '',
    subject: '',
    message: '',
  });
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleChange = (key: string, value: string) => {
    setFormData((prev) => ({ ...prev, [key]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      await apiClient.post('/leads', {
        ...formData,
        interestType: 'contact',
      });
      setSubmitted(true);
      toast.success(t('components.contactForm.success'));
    } catch (err: any) {
      toast.error(err.message || 'خطا در ارسال پیام. لطفا دوباره تلاش کنید.');
    } finally {
      setSubmitting(false);
    }
  };

  if (submitted) {
    return (
      <div className={className}>
        <div className="text-center py-8">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-emerald-100 text-emerald-600 mx-auto mb-4">
            <MessageSquare className="h-6 w-6" />
          </div>
          <h3 className="text-lg font-bold text-text-primary">{t('components.contactForm.success')}</h3>
          <p className="text-text-secondary text-sm mt-2">
            تیم ما به زودی با شما تماس می‌گیرد.
          </p>
        </div>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className={cn('space-y-6', className)}>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2">
          <Label htmlFor="fullName">{t('components.contactForm.nameLabel')}</Label>
          <div className="relative">
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
              <Mail className="h-4 w-4" />
            </div>
            <Input
              id="fullName"
              type="text"
              required
              value={formData.fullName}
              onChange={(e) => handleChange('fullName', e.target.value)}
              placeholder="علی محمدی"
              className="ps-9"
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="email">{t('components.contactForm.emailLabel')}</Label>
          <div className="relative">
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
              <Mail className="h-4 w-4" />
            </div>
            <Input
              id="email"
              type="email"
              required
              value={formData.email}
              onChange={(e) => handleChange('email', e.target.value)}
              placeholder="name@example.com"
              className="ps-9"
            />
          </div>
        </div>
      </div>
      <div className="space-y-2">
        <Label htmlFor="phone">{t('components.contactForm.phoneLabel')}</Label>
        <div className="relative">
          <div className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none">
            <Phone className="h-4 w-4" />
          </div>
          <Input
            id="phone"
            type="tel"
            value={formData.phone}
            onChange={(e) => handleChange('phone', e.target.value)}
            placeholder="۰۹۱۲۳۴۵۶۷۸۹"
            className="ps-9"
          />
        </div>
      </div>
      <div className="space-y-2">
        <Label htmlFor="subject">{t('components.contactForm.subjectLabel')}</Label>
        <Input
          id="subject"
          type="text"
          required
          value={formData.subject}
          onChange={(e) => handleChange('subject', e.target.value)}
          placeholder="موضوع پیام"
        />
      </div>
      <div className="space-y-2">
        <Label htmlFor="message">{t('components.contactForm.messageLabel')}</Label>
        <div className="relative">
          <div className="absolute left-3 top-3 text-slate-400 pointer-events-none">
            <MessageSquare className="h-4 w-4" />
          </div>
          <textarea
            id="message"
            rows={4}
            required
            value={formData.message}
            onChange={(e) => handleChange('message', e.target.value)}
            placeholder="پیام شما..."
            className="block w-full rounded-md border border-border bg-background px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary disabled:cursor-not-allowed disabled:opacity-50 pl-9"
          />
        </div>
      </div>
      <Button type="submit" disabled={submitting} className="w-full font-semibold">
        {submitting ? t('common.loading') : t('components.contactForm.submit')}
      </Button>
    </form>
  );
}

export default ContactForm;

