import React, { useState, useEffect } from 'react';
import { Toaster } from 'sileo';
import { HomePage } from './pages/public/HomePage';
import { LoginPage } from './pages/public/LoginPage';
import { RegisterPage } from './pages/public/RegisterPage';
import { ServicesPage } from './pages/public/ServicesPage';
import { PackagesPage } from './pages/public/PackagesPage';
import { PortfolioPage } from './pages/public/PortfolioPage';
import { AboutPage } from './pages/public/AboutPage';
import { BlogPage } from './pages/public/BlogPage';
import { ContactPage } from './pages/public/ContactPage';
import { AdminDashboardShell } from './pages/admin/AdminDashboardShell';
import { useAuth } from './hooks/useAuth';
import './styles/globals.css';

export function App() {
  const { isAuthenticated, user } = useAuth();
  const [currentRoute, setCurrentRoute] = useState<string>(() => {
    if (typeof window !== 'undefined') {
      const path = window.location.pathname.replace(/^\/(fa|en)/, '');
      if (path.startsWith('/admin')) return '/admin';
      if (path.startsWith('/login')) return '/login';
      if (path.startsWith('/register')) return '/register';
      if (path.startsWith('/services')) return '/services';
      if (path.startsWith('/packages')) return '/packages';
      if (path.startsWith('/portfolio')) return '/portfolio';
      if (path.startsWith('/about')) return '/about';
      if (path.startsWith('/blog')) return '/blog';
      if (path.startsWith('/contact')) return '/contact';
    }
    return '/';
  });

  const navigate = (to: string) => {
    setCurrentRoute(to);
    if (typeof window !== 'undefined') {
      window.history.pushState({}, '', to);
    }
  };

  useEffect(() => {
    const handlePopState = () => {
      const path = window.location.pathname.replace(/^\/(fa|en)/, '');
      if (path.startsWith('/admin')) setCurrentRoute('/admin');
      else if (path.startsWith('/login')) setCurrentRoute('/login');
      else if (path.startsWith('/register')) setCurrentRoute('/register');
      else if (path.startsWith('/services')) setCurrentRoute('/services');
      else if (path.startsWith('/packages')) setCurrentRoute('/packages');
      else if (path.startsWith('/portfolio')) setCurrentRoute('/portfolio');
      else if (path.startsWith('/about')) setCurrentRoute('/about');
      else if (path.startsWith('/blog')) setCurrentRoute('/blog');
      else if (path.startsWith('/contact')) setCurrentRoute('/contact');
      else setCurrentRoute('/');
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  // AC-20: Session protection on dashboard routes
  useEffect(() => {
    if (currentRoute === '/admin' && !isAuthenticated) {
      navigate('/login');
    }
  }, [currentRoute, isAuthenticated]);

  return (
    <>
      <Toaster position="top-center" />

      {currentRoute === '/login' && (
        <LoginPage
          onSuccess={() => navigate('/admin')}
          onNavigateRegister={() => navigate('/register')}
          onNavigateHome={() => navigate('/')}
        />
      )}

      {currentRoute === '/register' && (
        <RegisterPage
          onSuccess={() => navigate('/admin')}
          onNavigateLogin={() => navigate('/login')}
          onNavigateHome={() => navigate('/')}
        />
      )}

      {currentRoute === '/admin' && (
        isAuthenticated ? (
          <AdminDashboardShell
            onNavigateHome={() => navigate('/')}
            onNavigate={(path) => navigate(path)}
          />
        ) : (
          <LoginPage
            onSuccess={() => navigate('/admin')}
            onNavigateRegister={() => navigate('/register')}
            onNavigateHome={() => navigate('/')}
          />
        )
      )}

      {currentRoute === '/services' && <ServicesPage />}
      {currentRoute === '/packages' && <PackagesPage />}
      {currentRoute === '/portfolio' && <PortfolioPage />}
      {currentRoute === '/about' && <AboutPage />}
      {currentRoute === '/blog' && <BlogPage />}
      {currentRoute === '/contact' && <ContactPage />}

      {currentRoute === '/' && (
        <HomePage
          onNavigateLogin={() => navigate('/login')}
          onNavigateRegister={() => navigate('/register')}
          onNavigateAdmin={() => navigate('/admin')}
        />
      )}
    </>
  );
}

export default App;

